import { test, expect } from '../../../utils/infra/persistent-context';
import { InsightsListingPage } from '../../../pages/ga/components/insightsListingPage';
import ENV from '../../../utils/infra/env';
import { loginToAEMAuthor } from '../../../utils/infra/auth-fixture';

const BASE = () => ENV.AEM_AUTHOR_URL || 'http://localhost:4502';

test.beforeEach(async ({ page }) => {
  await loginToAEMAuthor(page);
});

/*
 * InsightsListing State Matrix
 *
 * 4 tests (2 valid + 1 responsive + 1 invalid).
 * Generated by state-matrix-generator.ts — viewport triplication collapsed.
 *
 * Selectors (from DOM probe):
 *   Background: component-level classes on .cmp-insights-listing
 *   Disabled overlays excluded via :not([aria-disabled="true"])
 */

// ── Valid: variant × theme × background at desktop (2 tests) ──

test.describe('InsightsListing — State Matrix (Valid)', () => {
    test('[INSIGHTS_LISTING-V] @matrix @regression default + dark-theme in white background', async ({ page }) => {
      const pom = new InsightsListingPage(page);
      await pom.navigate(BASE());
      const container = page.locator('.cmp-insights-listing').first();
      await expect(container).toBeVisible();
      const el = container;
      await expect(el).toBeVisible();
    });

    test('[INSIGHTS_LISTING-V] @matrix @regression default + auto-theme in white background', async ({ page }) => {
      const pom = new InsightsListingPage(page);
      await pom.navigate(BASE());
      const container = page.locator('.cmp-insights-listing').first();
      await expect(container).toBeVisible();
      const el = container;
      await expect(el).toBeVisible();
    });
});

// ── Responsive: one spot-check per background at mobile (1 tests) ──

test.describe('InsightsListing — State Matrix (Responsive)', () => {
    test('[INSIGHTS_LISTING-R] @matrix @regression @mobile insights-listing in white background @ mobile-390', async ({ page }) => {
      await page.setViewportSize({ width: 390, height: 844 });
      const pom = new InsightsListingPage(page);
      await pom.navigate(BASE());
      const container = page.locator('.cmp-insights-listing').first();
      await expect(container).toBeVisible();
      const el = container;
      await expect(el).toBeVisible();
    });
});

// ── Invalid: contrast concerns (1 tests) ──

test.describe('InsightsListing — State Matrix (Invalid Combos)', () => {
    test('[INSIGHTS_LISTING-N] @matrix @negative default + light-theme on white (light-on-light)', async ({ page }) => {
      // light-theme on light background (white) has insufficient contrast
      // Auto-theme should be used instead. Verify container still renders.
      const pom = new InsightsListingPage(page);
      await pom.navigate(BASE());
      const container = page.locator('.cmp-insights-listing').first();
      await expect(container).toBeVisible();
    });
});
